// quantity: the months HR counted under art.47(2); zero still pays the two-month minimum (Decree 145/2020 art.8(2)).
const terms = ctx.subject.employment.terms;
const fixed = Object.entries(get(terms, 'allowances', {})).reduce(
	(total, [code, allowance]) => ctx.lookup.excluded_allowances.includes(code) || get(allowance, 'fixed', true) === false ? total : total + Number(get(allowance, 'amount', 0)),
	0
);
const wage =
	get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY'
		? Number(get(terms, 'rate.amount', 0)) + fixed
		: ctx.day_rate * ctx.lookup.fallback_working_days;
const full_years = Math.trunc(ctx.entry.quantity / ctx.lookup.months_per_year);
const remainder = ctx.entry.quantity % ctx.lookup.months_per_year;
const pay = (years) => wage * Math.max(years, ctx.lookup.minimum_months);
if (remainder > ctx.lookup.half_year_remainder_months) return pay(full_years + 1);
if (remainder > 0) return pay(full_years + ctx.lookup.half_year_share);
return pay(full_years);

